15	const BASE_PREMIUM: Record<string, number> = {
16	  sword: 100,
17	  amulet: 60,
18	  staff: 80,
19	  potion: 40,
20	  rune: 25,
21	};
22	
23	const PROCESSING_FEE = 5;
24	const FIRST_INSURANCE_SURCHARGE = 0.1;
25	
26	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
27	const COMPONENT_UNIT_PREMIUM = 25;
28	const COMPONENT_BLOCK_SIZE = 3;
29	const COMPONENT_BLOCK_PREMIUM = 60;
30	
31	const componentGroupBase = (count: number): number =>
32	  count === COMPONENT_BLOCK_SIZE
33	    ? COMPONENT_BLOCK_PREMIUM
34	    : count * COMPONENT_UNIT_PREMIUM;
35	
36	const componentsBase = (components: { type: string }[]): number => {
37	  const countsByType = new Map<string, number>();
38	  for (const component of components) {
39	    countsByType.set(component.type, (countsByType.get(component.type) ?? 0) + 1);
40	  }
41	  return [...countsByType.values()].reduce(
42	    (total, count) => total + componentGroupBase(count),
43	    0,
44	  );
45	};
46	
47	const isComponent = (item: { type: string }): boolean =>
48	  COMPONENT_TYPES.has(item.type);
49	
50	const itemsBase = (items: { type: string }[]): number => {
51	  const mainBase = items
52	    .filter((item) => !isComponent(item))
53	    .reduce((sum, item) => sum + BASE_PREMIUM[item.type], 0);
54	  return mainBase + componentsBase(items.filter(isComponent));
55	};
56	
57	const CURSE_SURCHARGE = 0.5;
58	
59	const curseSurcharge = (items: { type: string; cursed?: boolean }[]): number =>
60	  items.reduce(
61	    (sum, item) => sum + (item.cursed ? BASE_PREMIUM[item.type] * CURSE_SURCHARGE : 0),
62	    0,
63	  );
64	
65	const quotePremium = (items: { type: string; cursed?: boolean }[]): number => {
66	  const base = itemsBase(items);
67	  // Keep as `base + base * rate`, not `base * (1 + rate)`: the additive form
68	  // avoids IEEE-754 drift that would otherwise round wrong under Math.ceil.
69	  return Math.ceil(
70	    base + base * FIRST_INSURANCE_SURCHARGE + curseSurcharge(items) + PROCESSING_FEE,
71	  );
72	};
73	
74	export const runScenario = (scenario: Scenario): { results: QuoteResult[] } => {
75	  const results = scenario.steps.map((step) => ({
76	    premium: quotePremium(step.items),
77	  }));
78	  return { results };
79	};
